var EXTRA=[{dot:"gray",j:"Arthroscopy",h:"Una tecnica tutta artroscopica per le fratture da avulsione del LCP",v:"serie retrospettiva di 22 pazienti: fissazione a 3 tunnel con ponte di sutura per la frattura da avulsione tibiale del legamento crociato posteriore, miglioramento significativo di IKDC/Lysholm/Tegner e traslazione tibiale posteriore (KT-1000) a 24 mesi, nessuna complicanza; livello IV, senza gruppo di confronto.",pmid:'42681948',doi:'10.1002/arj.70502',temi:["lcp","traumatologia","tecnica chirurgica"]},{dot:"gray",j:"Arthroscopy",h:"Un modello economico a 30 anni confronta trapianto osteocondrale, monocompartimentale e protesi totale",v:"modello di Markov teorico su pazienti attivi di 40 anni: la protesi monocompartimentale risulta la più costo-efficace nel breve periodo, il trapianto osteocondrale multi-superficie il più costoso ma con il maggior guadagno di qualità di vita cumulata nei primi 10 anni; dati computazionali, non uno studio clinico.",pmid:'42681997',doi:'10.1002/arj.70495',temi:["cartilagine","economia sanitaria","protesi monocompartimentale"]},{dot:"gray",j:"Orthopaedic Journal of Sports Medicine",h:"Nell'osteotomia tibiale alta, la densità ossea si sposta dove va il carico",v:"coorte giapponese di 27 ginocchia: dopo osteotomia tibiale alta a cuneo di apertura, quanto più si riduce la densità ossea subcondrale nel compartimento mediale, tanto migliori sono Lysholm e KOOS a 2 anni — un possibile marcatore per immagini dello scarico del compartimento operato.",pmid:'42682739',doi:'10.1177/23259671261444313',temi:["osteotomia","imaging","biomeccanica"]},{dot:"gray",j:"Orthopaedic Journal of Sports Medicine",h:"Meno della metà degli allenatori delle liceali usa un protocollo specifico anti-LCA",v:"sondaggio fra allenatori di basket/calcio/volley femminile a Detroit: la maggioranza conosce i programmi di prevenzione del LCA, ma solo una minoranza ne usa uno specifico; le scuole a status socioeconomico più basso hanno meno consapevolezza.",pmid:'42682899',doi:'10.1177/23259671261470580',temi:["prevenzione","lca","adolescenti"]},{dot:"gray",j:"Osteoarthritis and Cartilage",h:"L'artrosi di ginocchio sintomatica colpisce oggi più che nelle coorti storiche",v:"partecipanti dello studio della contea di Johnston: la prevalenza di artrosi radiografica sintomatica risulta più alta delle stime storiche della stessa coorte; più frequente nelle donne e nell'obesità severa, con pattern ecografici diversi fra i sessi.",pmid:'42679988',doi:'10.1016/j.joca.2026.08.012',temi:["artrosi","epidemiologia","imaging"]},{dot:"gray",j:"Academic Radiology",h:"Il volume del muscolo della coscia alla RM predice l'artrosi di ginocchio che verrà",v:"oltre 7.100 cosce nello studio OAI: un vasto mediale più voluminoso all'inizio si associa a minor rischio di artrosi incidente e progressiva, mentre più tessuto adiposo intramuscolare nello stesso muscolo si associa a rischio maggiore — un possibile marcatore per immagini da validare in studi prospettici dedicati.",pmid:'42680660',doi:'10.1016/j.acra.2026.08.056',temi:["artrosi","imaging","biomeccanica"]},{dot:"gray",j:"Journal of Orthopaedic & Sports Physical Therapy",h:"Nell'artrosi di ginocchio, il volume dell'esercizio contro resistenza ha una dose ottimale",v:"revisione con meta-analisi dose-risposta di 20 RCT (791 pazienti): il massimo beneficio sul dolore si osserva verso 6.000 ripetizioni cumulative, sulla funzione verso 2.600 a intensità moderata; certezza dell'evidenza bassa o molto bassa secondo GRADE.",pmid:'42676087',doi:'10.2519/jospt.2026.13477',temi:["artrosi","riabilitazione","esercizio"]},{dot:"gray",j:"Ultrasound",h:"L'ecografia del ginocchio si affianca alla radiografia nel misurare l'artrosi",v:"studio trasversale iraniano: osteofiti femorali mediali, versamento sovrarotuleo, cisti di Baker e protrusione meniscale mediale all'ecografia correlano con il grado radiografico Kellgren-Lawrence e, insieme, con il dolore riferito — la radiografia da sola non correla con il dolore.",pmid:'42682872',doi:'10.1177/1742271X261459305',temi:["artrosi","imaging","ecografia"]},{dot:"gray",j:"Turkish Journal of Physical Medicine and Rehabilitation",h:"La radiofrequenza dei nervi genicolati migliora anche l'equilibrio, non solo il dolore",v:"22 pazienti con artrosi di ginocchio trattati con ablazione a radiofrequenza dei nervi genicolati per il dolore: oltre alla riduzione del dolore, migliorano anche parametri di stabilità posturale dinamica a 3 settimane e 3 mesi — piccola serie, nessun gruppo di controllo.",pmid:'42675862',doi:'10.4274/tftrd.2025.16094',temi:["artrosi","dolore","riabilitazione"]},{dot:"gray",j:"Frontiers in Physiology",h:"Le prestazioni cognitive di base modulano la biomeccanica del rischio LCA nel cambio di direzione",v:"30 calciatori di alto livello: il cambio di direzione non anticipato aumenta angolo e momento di abduzione del ginocchio rispetto a quello anticipato, e tempo di reazione ed errori a un test cognitivo Go/No-Go modulano queste risposte biomeccaniche — collega prestazione cognitiva e rischio di infortunio nel gesto sportivo reale.",pmid:'42682411',doi:'10.3389/fphys.2026.1911093',temi:["lca","prevenzione","biomeccanica"]},{dot:"gray",j:"Scandinavian Journal of Medicine & Science in Sports",h:"Dopo una maratona, il menisco mediale si gonfia un po' e torna normale in 4 giorni",v:"podisti amatoriali seguiti dopo una maratona: l'estrusione del menisco mediale aumenta subito dopo la gara e resta elevata per alcuni giorni, tornando poi ai valori di base; l'aumento è maggiore in chi carica di più sul compartimento mediale durante la corsa, con BMI più alto o più chilometri mensili.",pmid:'42683665',doi:'10.1111/sms.70366',temi:["menisco","estrusione","corsa"]},{dot:"gray",j:"Seminars in Arthritis and Rheumatism",h:"La colchicina non riduce il dolore da artrosi di ginocchio in un RCT di 3 mesi",v:"120 pazienti, doppio cieco contro placebo, senza FANS concomitanti: nessuna differenza significativa su dolore, punteggi KOOS o dimensione del versamento; alcuni biomarcatori infiammatori sierici migliorano comunque con la colchicina, un segnale che gli autori giudicano da confermare a più lungo termine.",pmid:'42679472',doi:'10.1016/j.semarthrit.2026.153066',temi:["artrosi","farmaco","rct"]},{dot:"gray",j:"Medicine",h:"Due proteine plasmatiche si legano all'artrosi di ginocchio in un'analisi di randomizzazione mendeliana",v:"analisi genetica su migliaia di proteine e metaboliti plasmatici: IGFBP3 associata a maggior rischio di artrosi di ginocchio, collagene XVIII alfa-1 a rischio minore, con 20 metaboliti che mediano l'effetto — biologia esplorativa, lontana dalla pratica clinica quotidiana.",pmid:'42675719',doi:'10.1097/MD.0000000000050393',temi:["artrosi","genetica","biologia"]}];
var SCOPERTE=[{t:"Uno scaffold biodegradabile più cellule staminali del grasso ripara la cartilagine nella pecora",v:"Modello preclinico ovino (24 pecore, difetti condrali a tutto spessore sul condilo femorale mediale): uno scaffold di polidiossanone, biodegradabile e biocompatibile, combinato con cellule staminali mesenchimali allogeniche derivate dal grasso produce a 26 settimane una cartilagine più simile a quella ialina rispetto allo scaffold di collagene o alla sola microfrattura, con più collagene di tipo II e meno di tipo I e X. È bioingegneria di frontiera, non una tecnologia clinica: la strada dal modello ovino all'uomo è lunga, ma la direzione — scaffold su misura più cellule, invece del solo microfrattura — è la stessa in cui si muove la ricerca sulla cartilagine che segui.",pmid:'42676619',doi:'10.1016/j.jot.2026.101193',temi:["cartilagine","bioingegneria","cellule staminali"]},{t:"Un algoritmo di machine learning distingue due «tipi» di artrosi di ginocchio dal solo modo di camminare",v:"66 donne con artrosi di ginocchio moderata (27 candidate a protesi, 39 in trattamento conservativo): un classificatore Random Forest allenato sulla sola cinematica dell'appoggio — in particolare l'inclinazione del bacino — distingue i due gruppi con un'accuratezza dell'81% (area sotto la curva ROC), pur avendo lo stesso grado radiografico Kellgren-Lawrence. Segnala che l'analisi del cammino, oggi poco usata nella pratica clinica quotidiana, potrebbe un giorno aiutare a capire chi si avvia davvero verso la protesi anche quando la radiografia da sola non basta a deciderlo.",pmid:'42682814',doi:'10.3389/fbioe.2026.1903640',temi:["intelligenza artificiale","artrosi","biomeccanica"]}];
var SOC={"1":{video:"Experimental and Therapeutic Medicine ha pubblicato un'Expression of Concern su uno studio cinese sugli effetti del plasma ricco di piastrine nell'artrosi di ginocchio: la rivista non spiega ancora il motivo della segnalazione. Non è un lavoro mai citato in queste pagine — verificato oggi l'intero perimetro storico del progetto, 154 citazioni, nessuna ritrattazione trovata — ma è un promemoria che la letteratura sul PRP nell'artrosi non è esente da problemi di integrità, lo stesso tema toccato dalla scheda sulla distorsione nelle revisioni sul PRP nella sutura meniscale."},"2":{video:"Uno studio caso-controllo su 72 rifissazioni della radice meniscale mediale mostra che uno slope tibiale posteriore più alto predice in modo indipendente il mancato consolidamento a 6 mesi (OR 1,31 per grado; IC 95% 1,04-1,73). Tecnica di fissazione diversa da quella più diffusa in Europa, ma il principio biomeccanico — più inclinazione della tibia, più rischio di non guarigione — si aggiunge alla tensione già aperta sull'estrusione meniscale."},"3":{video:"Una meta-analisi di 9 studi comparativi (937 protesi) sul robot MAKO conferma un allineamento più preciso e punteggi funzionali migliori rispetto alla tecnica convenzionale, ma lascia senza risposta chiara dolore, range di movimento e Forgotten Joint Score — lo schema già visto sul RCT RACER-Knee di fine agosto, qui su una piattaforma robotica diversa."},"4":{video:"Una revisione metodologica su 16 sintesi pubblicate sul PRP nella sutura meniscale trova almeno una distorsione a favore del trattamento in 15 casi su 16 (93,8%), spesso insieme a una qualità metodologica criticamente bassa. Non dice se il PRP funzioni: dice che il modo in cui la letteratura lo racconta va letto con più cautela del solito."},"5":{video:"Una serie retrospettiva turca segue per 14 anni 42 pazienti operati di resezione della plica mediopatellare con degenerazione cartilaginea associata: il 92,9% mantiene un risultato buono o eccellente al WOMAC. Manca un gruppo di controllo, quindi lo studio non isola il contributo della chirurgia dalla storia naturale, ma il follow-up è insolitamente lungo per questo tipo di intervento."},"6":{video:"In 59 pazienti operati insieme di ricostruzione del LCA e sutura di una lesione meniscale a manico di secchio, il grado di ricopertura sinoviale del neolegamento osservato al second-look si correla fortemente con la guarigione della sutura meniscale (r=0,724). Un indicatore biologico intraoperatorio per una combinazione chirurgica che si pratica spesso, anche se i sottogruppi non sono riportati per numerosità esatta."},"7":{video:"Un registro riabilitativo svedese su 1.508 pazienti mostra che, a 24 mesi, il rientro all'attività fisica preinfortunio è più frequente dopo LCA primaria (43,9%) che dopo revisione (27,1%) o controlaterale (25,7%). Le differenze di forza muscolare restano modeste, ma i punteggi riferiti dal paziente favoriscono sempre la primaria — un dato utile per calibrare le aspettative prima di un secondo intervento."}};
var SOCV={"1":{video:{chir:["Una rivista medica, Experimental and Therapeutic Medicine, ha pubblicato un'Expression of Concern su uno studio cinese sugli effetti del plasma ricco di piastrine nell'artrosi di ginocchio tramite soppressione di fattori infiammatori. È un avviso ufficiale della rivista, non una ritrattazione: il lavoro resta pubblicato, ma sotto verifica.","La nota non spiega le ragioni della preoccupazione: non sappiamo se riguardi i dati, il metodo statistico o un conflitto d'interesse non dichiarato. Non è un lavoro mai citato in queste pagine: controllato oggi l'intero perimetro storico del progetto, 154 citazioni riaperte su PubMed, nessuna ritrattazione trovata fra quelle già usate.","È comunque un promemoria utile: la letteratura sul plasma ricco di piastrine nell'artrosi, un'area seguita con attenzione, non è esente da problemi di integrità scientifica. Nella stessa giornata, una revisione metodologica separata mostra che quasi il 94% delle sintesi sul PRP nella sutura meniscale ne esagera i risultati — la cautela va estesa a tutto il tema, non solo a questo singolo caso."],misto:["Una rivista scientifica ha reso pubblica una nota ufficiale di attenzione su uno studio cinese riguardante il plasma ricco di piastrine (PRP) nell'artrosi di ginocchio. Si chiama Expression of Concern: il lavoro non viene ritirato, ma la rivista segnala che qualcosa in quello studio merita una verifica più approfondita.","Al momento non è stato reso pubblico il motivo esatto della segnalazione. È comunque un lavoro diverso da quelli già discussi in queste pagine, ed è stato verificato che nessuna delle 154 citazioni già usate nel progetto risulti ritirata o sotto la stessa procedura.","È un segnale utile per chi si informa sul plasma ricco di piastrine come trattamento per l'artrosi: non tutto ciò che viene pubblicato resta valido nel tempo, e conviene sempre affidarsi al giudizio del proprio medico più che a un singolo studio."],pazienti:["Una rivista medica ha segnalato ufficialmente dei dubbi su uno studio cinese che riguardava il plasma ricco di piastrine, un trattamento di cui si sente parlare spesso per l'artrosi del ginocchio.","Non si sa ancora con precisione perché: la rivista non ha reso pubblico il motivo. Il lavoro non è stato ritirato, resta pubblicato, ma sotto osservazione.","È giusto saperlo, senza allarmarsi: anche nella ricerca scientifica capita che un lavoro venga rivisto con più attenzione dopo la pubblicazione, ed è proprio così che il sistema della scienza corregge sé stesso nel tempo."]},reel:{chir:["Expression of Concern su uno studio cinese sul PRP nell'artrosi di ginocchio.","La rivista non spiega ancora il motivo. Non è mai stato citato in queste pagine.","[testo a schermo: «PRP artrosi · sotto verifica editoriale»] Stesso giorno: 94% delle revisioni sul PRP nella sutura meniscale ne esagera i risultati."],misto:["Un lavoro scientifico sul plasma ricco di piastrine nell'artrosi finisce sotto controllo editoriale.","Non è ritirato, solo segnalato per una verifica più attenta — il motivo non è ancora pubblico.","[testo a schermo: «Attenzione editoriale, non ritiro»] Un promemoria di cautela su un tema molto discusso."],pazienti:["Uno studio sul plasma ricco di piastrine nell'artrosi è sotto verifica.","Non è stato ritirato: la rivista chiede solo un controllo più attento.","[testo a schermo: «La scienza si corregge da sola»] Un segnale di trasparenza, non di allarme."]},linkedin:{chir:["PRP nell'artrosi: un lavoro cinese sotto Expression of Concern","Experimental and Therapeutic Medicine ha pubblicato un'Expression of Concern su uno studio cinese sugli effetti del plasma ricco di piastrine nell'artrosi di ginocchio tramite soppressione di fattori infiammatori (Huang, Hua, Yang, Ma, Yu, Chen; 2026;32(4):274).\n\nLa nota non specifica il motivo della preoccupazione. Non è un lavoro mai citato in questo progetto: controllate oggi tutte le 154 citazioni storiche, nessuna ritrattazione trovata.","Nella stessa giornata, una revisione metodologica separata (OJSM) mostra che il 93,8% delle sintesi pubblicate sul PRP nella sutura meniscale contiene almeno una forma di distorsione a favore del trattamento. Due segnali indipendenti sullo stesso tema, nello stesso giorno."],misto:["Uno studio sul plasma ricco di piastrine nell'artrosi finisce sotto controllo editoriale","La rivista Experimental and Therapeutic Medicine ha reso pubblica un'Expression of Concern — una nota ufficiale di attenzione — su uno studio cinese riguardante gli effetti del plasma ricco di piastrine nell'artrosi di ginocchio.\n\nIl lavoro non è stato ritirato, resta pubblicato ma sotto verifica; il motivo esatto non è stato reso pubblico.","Non è un lavoro mai citato in queste pagine. È comunque un promemoria utile: anche la letteratura su un trattamento molto discusso come il PRP va letta con occhio critico, e la scienza corregge sé stessa nel tempo, pubblicamente."],pazienti:["Un lavoro scientifico sul plasma ricco di piastrine è sotto verifica","Una rivista medica ha segnalato ufficialmente dei dubbi su uno studio cinese riguardante il plasma ricco di piastrine nell'artrosi di ginocchio, un trattamento di cui si sente parlare spesso.","Non è stato ritirato, solo messo sotto osservazione. È un buon esempio di come la scienza si corregga da sola, pubblicamente, quando serve."]},instagram:{chir:["⚠️ PRP e artrosi: un lavoro cinese sotto Expression of Concern\n\nLa rivista non ritira lo studio, ma segnala una preoccupazione ufficiale.","Non è un lavoro mai citato qui. Controllate oggi tutte le 154 citazioni storiche del progetto: nessuna ritrattazione.\n\nStesso giorno: il 94% delle revisioni sul PRP nella sutura meniscale ne esagera i risultati.","📎 Link in bio · Experimental and Therapeutic Medicine"],misto:["⚠️ Un lavoro sul plasma ricco di piastrine (PRP) nell'artrosi finisce sotto controllo\n\nLa rivista lo segnala ufficialmente, senza ritirarlo.","Il motivo non è ancora pubblico. Vale come promemoria: anche la ricerca su trattamenti molto discussi va letta con occhio critico.","📎 Link in bio"],pazienti:["⚠️ Uno studio sul plasma ricco di piastrine è sotto verifica\n\nNon è stato ritirato: solo segnalato per un controllo più attento.","È un buon esempio di come la scienza corregga sé stessa, pubblicamente, nel tempo.","📎 Il link nella descrizione del profilo"]}},"2":{video:{chir:["Uno studio caso-controllo coreano su due centri, 72 rifissazioni della radice meniscale mediale con tecnica all-inside, cerca un fattore di rischio preoperatorio per il mancato consolidamento — poco studiato finora, rispetto a quanto si sa già sugli esiti clinici dopo l'intervento.","Il risultato: lo slope tibiale posteriore mediale è significativamente più alto in chi non guarisce, 5,9 gradi contro 4,4 nel gruppo guarito (p=0,017). Alla regressione logistica, ogni grado in più di slope alza il rischio di mancato consolidamento del 31% (odds ratio 1,31, intervallo di confidenza al 95% da 1,04 a 1,73, p=0,022) — età e indice di massa corporea non risultano invece associati.","Il limite tecnico conta: qui la fissazione è all-inside con ancora, non transtibiale pull-out. Il principio biomeccanico — più inclinazione della tibia, più forza di taglio anteriore, più rischio — è probabilmente valido anche per altre tecniche, ma il numero preciso resta legato a questo studio specifico, e alimenta la tensione aperta sull'estrusione della radice meniscale."],misto:["Uno studio su 72 pazienti operati per riparare la radice del menisco mediale, un tipo particolare di lesione meniscale grave, cerca di capire quali pazienti guariscono e quali no dopo l'intervento.","Il dato interessante: chi ha, in partenza, un'inclinazione naturale più marcata dell'osso della tibia guarisce meno spesso completamente — la differenza è statisticamente significativa — mentre l'età e il peso corporeo non sembrano influire allo stesso modo.","È uno studio su una tecnica chirurgica specifica, diversa da quella più diffusa in Europa: il principio generale — più inclinazione ossea, più difficoltà a guarire — è probabilmente valido più in generale, ma il numero esatto resta legato a questo studio."],pazienti:["Uno studio ha seguito 72 pazienti operati per riparare una lesione grave del menisco, vicino al punto in cui è ancorato all'osso, per capire perché alcuni guariscono bene e altri no.","È emerso che un particolare dettaglio anatomico — l'inclinazione naturale dell'osso della tibia, diversa da persona a persona — è collegato a una guarigione più difficile, mentre l'età e il peso corporeo non sembrano avere lo stesso peso.","Non è un motivo per non operarsi: è un'informazione in più che il chirurgo può usare per spiegare, prima dell'intervento, che cosa aspettarsi dalla guarigione nel singolo caso."]},reel:{chir:["72 rifissazioni della radice meniscale mediale: che cosa predice il mancato consolidamento?","Slope tibiale posteriore più alto = più rischio. OR 1,31 per grado (IC 95% 1,04-1,73, p=0,022).","[testo a schermo: «Slope alto → più rischio di non guarigione»] Tecnica all-inside, non transtibiale: principio trasferibile, numero no."],misto:["Riparare il menisco lesionato alla radice: che cosa fa guarire meglio?","L'inclinazione naturale della tibia conta: più è marcata, più difficile la guarigione completa.","[testo a schermo: «Un dettaglio anatomico che pesa sulla guarigione»] Età e peso corporeo non sembrano influire allo stesso modo."],pazienti:["Riparare una lesione grave del menisco: che cosa influenza la guarigione?","Un dettaglio anatomico dell'osso della tibia, diverso da persona a persona, sembra contare.","[testo a schermo: «Un'informazione in più per il colloquio col chirurgo»] Non impedisce l'intervento, aiuta a capire le probabilità."]},linkedin:{chir:["Radice meniscale: uno slope tibiale più alto alza il rischio di mancata guarigione","Studio caso-controllo, due centri coreani (Choi, Yang, Lee, Victoroff; OJSM, settembre 2026): 72 rifissazioni all-inside con ancora della radice meniscale posteriore mediale, guarigione valutata su RM a 6 mesi.\n\nLo slope tibiale posteriore mediale è significativamente più alto nel gruppo non guarito (5,9°±2,2° vs 4,4°±2,5°; p=0,017). OR 1,31 per grado di slope (IC 95% 1,04-1,73; p=0,022); età e BMI non associati.","Limite da tenere presente: tecnica di fissazione all-inside con ancora, non transtibiale pull-out. Il principio biomeccanico è verosimilmente lo stesso indipendentemente dalla tecnica, il numero esatto no. Alimenta la tensione aperta sull'estrusione della radice meniscale."],misto:["Riparare il menisco alla radice: l'inclinazione della tibia influenza la guarigione","Uno studio su 72 pazienti operati per riparare la radice del menisco mediale mostra che chi ha un'inclinazione naturale più marcata della tibia guarisce con più difficoltà, indipendentemente da età e peso corporeo.\n\nÈ una tecnica di fissazione diversa da quella più diffusa in Europa (con ancora, non con tunnel tibiale), ma il principio generale è probabilmente valido più in generale.","Un dettaglio anatomico in più da considerare nel colloquio prima dell'intervento, non un motivo per rinunciarvi."],pazienti:["Riparare il menisco lesionato: un dettaglio anatomico che conta per la guarigione","Uno studio su pazienti operati per riparare una lesione grave del menisco mostra che un'inclinazione naturale più marcata dell'osso della tibia è collegata a una guarigione più difficile.","È un'informazione utile per il colloquio col chirurgo prima dell'intervento, non un ostacolo all'operazione in sé."]},instagram:{chir:["🦵 Radice meniscale: lo slope tibiale predice la guarigione\n\n72 rifissazioni, due centri, tecnica all-inside.","OR 1,31 per grado di slope (IC 95% 1,04-1,73, p=0,022). Età e BMI non associati.\n\nTecnica diversa dalla transtibiale pull-out: principio trasferibile, numero no.","📎 Link in bio · OJSM, settembre 2026"],misto:["🦵 Riparare il menisco alla radice: l'inclinazione della tibia conta\n\n72 pazienti operati, guarigione valutata a 6 mesi.","Chi ha un'inclinazione naturale più marcata guarisce con più difficoltà — età e peso corporeo non influiscono allo stesso modo.","📎 Link in bio"],pazienti:["🦵 Un dettaglio anatomico che aiuta a capire la guarigione del menisco\n\nUno studio su pazienti operati per una lesione grave del menisco.","Un'inclinazione naturale dell'osso della tibia, diversa da persona a persona, è collegata a una guarigione più difficile.","📎 Il link nella descrizione del profilo"]}},"3":{video:{chir:["Una meta-analisi cinese mette insieme 9 studi comparativi, 937 protesi totali di ginocchio, per confrontare il robot MAKO con la tecnica convenzionale: nessuno studio randomizzato incluso, solo comparativi osservazionali retrospettivi o prima-dopo.","Il robot allinea meglio: l'angolo anca-ginocchio-caviglia si avvicina di più al target (differenza media -0,96 gradi, intervallo di confidenza al 95% da -1,26 a -0,65, p<0,0001), e i punteggi funzionali del ginocchio sono migliori (differenza standardizzata 0,46, p=0,04). Ma su dolore, range di movimento e Forgotten Joint Score — l'indicatore che misura quanto il paziente «dimentica» di avere un ginocchio operato — le differenze non raggiungono la significatività statistica, con intervalli che non escludono comunque un vantaggio reale.","È lo stesso schema già visto sul RCT RACER-Knee di fine agosto e sulla revisione critica del 1° settembre: precisione tecnica dimostrata, beneficio funzionale percepito dal paziente ancora incerto. Qui la piattaforma è MAKO, diversa da quella con cui operi tu."],misto:["Una sintesi di 9 studi, quasi 940 protesi di ginocchio operate con l'assistenza del robot MAKO, confronta questa tecnologia con la chirurgia tradizionale.","Il robot posiziona la protesi in modo più preciso e alcuni punteggi funzionali risultano migliori. Ma su tre cose che contano molto per il paziente — il dolore, quanto si riesce a piegare il ginocchio, e quanto ci si «dimentica» di averlo operato — i risultati non sono ancora abbastanza chiari da dire con certezza se il robot faccia davvero la differenza.","È un quadro che si ripete: la tecnologia migliora la precisione tecnica dell'intervento, ma il vantaggio percepito dal paziente resta da dimostrare con studi randomizzati veri, che qui mancano del tutto."],pazienti:["Uno studio ha messo insieme i risultati di più ricerche su quasi 940 protesi di ginocchio operate con l'aiuto di un braccio robotico chiamato MAKO, confrontandole con l'intervento tradizionale.","Il robot aiuta a posizionare la protesi in modo più preciso, e alcuni punteggi di funzione risultano leggermente migliori. Ma non è ancora chiaro se questo si traduca davvero in meno dolore o in un ginocchio che il paziente sente più «normale» dopo l'intervento.","Non è quindi ancora dimostrato che l'intervento col robot dia un risultato migliore per chi lo riceve: la maggiore precisione tecnica, da sola, non basta a garantirlo."]},reel:{chir:["9 studi, 937 protesi: robot MAKO vs tecnica convenzionale.","Allineamento migliore, funzione migliore. Dolore, ROM, Forgotten Joint Score: muti.","[testo a schermo: «Precisione sì, beneficio percepito ancora incerto»] Come RACER-Knee, piattaforma diversa."],misto:["Protesi di ginocchio col robot MAKO: più precisa, ma il paziente lo sente di più?","Allineamento migliore, funzione migliore su carta — dolore e movimento ancora incerti.","[testo a schermo: «Tecnica sì, sensazione del paziente da dimostrare»] Nessuno studio randomizzato incluso."],pazienti:["Protesi di ginocchio con il robot MAKO: quanto cambia per chi la riceve?","Il posizionamento è più preciso, ma non è ancora chiaro se si senta davvero la differenza.","[testo a schermo: «Precisione tecnica ≠ garanzia di risultato»] Servono ancora studi randomizzati."]},linkedin:{chir:["Il robot MAKO migliora l'allineamento della protesi, non chiaramente la funzione","Meta-analisi di 9 studi comparativi, 937 TKA (Zhang, Lou, Wu, Ying, Chen; Frontiers Bioeng Biotechnol, agosto 2026): HKA più vicino al target col MAKO (MD -0,96°; IC 95% -1,26/-0,65; p<0,0001), punteggi funzionali migliori (SMD 0,46; p=0,04).\n\nDolore (p=0,07), ROM (p=0,12) e Forgotten Joint Score (p=0,09) restano non significativi, con intervalli ampi: risultati muti, non negativi.","Nessuno studio randomizzato incluso. Stesso schema di RACER-Knee (21 agosto) e della revisione critica del 1° settembre: precisione dimostrata, beneficio funzionale ancora da confermare. Piattaforma MAKO, non VELYS."],misto:["Protesi robotica MAKO: più precisione, beneficio per il paziente ancora da chiarire","Una sintesi di 9 studi su quasi 940 protesi di ginocchio operate col robot MAKO mostra un allineamento più accurato e alcuni punteggi funzionali migliori rispetto alla tecnica tradizionale.\n\nSu dolore, movimento e sensazione soggettiva del ginocchio operato, però, i risultati non sono ancora abbastanza chiari.","Nessuno degli studi inclusi è randomizzato: la tecnologia migliora la precisione tecnica, il vantaggio realmente percepito dal paziente resta da dimostrare."],pazienti:["Protesi di ginocchio con il robot: più precisione, ma quanto cambia per chi la riceve?","Una sintesi di più studi su quasi 940 protesi mostra che il robot MAKO posiziona la protesi in modo più preciso, con alcuni punteggi funzionali leggermente migliori rispetto alla tecnica tradizionale.","Non è però ancora dimostrato che questo significhi meno dolore o un recupero percepito come migliore: la precisione tecnica, da sola, non basta a garantirlo."]},instagram:{chir:["🤖 Robot MAKO in protesi di ginocchio: più preciso, non chiaramente più efficace\n\n9 studi, 937 protesi.","Allineamento e funzione migliori. Dolore, movimento, Forgotten Joint Score: ancora muti.\n\nNessuno studio randomizzato incluso.","📎 Link in bio · Frontiers Bioeng Biotechnol"],misto:["🤖 Protesi col robot MAKO: più precisa, ma il paziente lo sente di più?\n\nUna sintesi di 9 studi su quasi 940 protesi.","Allineamento migliore, alcuni punteggi funzionali migliori — dolore e movimento ancora incerti.","📎 Link in bio"],pazienti:["🤖 Protesi di ginocchio col robot: quanto cambia davvero?\n\nIl posizionamento è più preciso.","Non è ancora chiaro se questo si traduca in meno dolore o in un recupero migliore percepito dal paziente.","📎 Il link nella descrizione del profilo"]}},"4":{video:{chir:["Un gruppo dell'UCLA analizza 16 revisioni sistematiche e meta-analisi pubblicate sul plasma ricco di piastrine come augmentazione della sutura meniscale, cercando segni di «spin» — distorsione nella presentazione dei risultati rispetto a quanto i dati dimostrano davvero.","Il risultato è netto: almeno una forma di spin bias è presente in 15 revisioni su 16, il 93,8%. Le distorsioni più comuni sono non riportare un intervallo di confidenza ampio, concentrare la conclusione solo sull'esito favorevole con significatività statistica, ed enfatizzare selettivamente gli esiti a favore del PRP — ciascuna presente nel 43,8% delle revisioni. La qualità metodologica, misurata con lo strumento AMSTAR 2, è criticamente bassa nel 68,8% dei casi.","Non dice se il PRP funzioni o no come augmentazione della sutura meniscale: dice che, in questo campione, la sintesi che si legge nell'abstract di una revisione sistematica su questo tema ha quasi il 94% di probabilità di essere presentata in modo più favorevole di quanto i dati sottostanti giustifichino — la stessa cautela già raccomandata per le meta-analisi di PRP e cellule staminali nell'artrosi."],misto:["Un gruppo di ricercatori americani ha esaminato 16 revisioni scientifiche pubblicate sull'uso del plasma ricco di piastrine come aiuto alla guarigione del menisco riparato chirurgicamente, per capire se i risultati vengono raccontati in modo corretto.","Il risultato: in quasi tutte queste revisioni — 15 su 16 — i risultati vengono presentati in modo più ottimista di quanto i dati reali giustifichino, spesso insieme a una qualità metodologica bassa dello studio stesso.","Non significa che il plasma ricco di piastrine non funzioni: significa che, su questo tema specifico, conviene leggere le sintesi scientifiche con più cautela del solito, senza fermarsi al solo titolo o all'abstract."],pazienti:["Un gruppo di ricercatori ha controllato 16 studi scientifici che riassumevano le ricerche sull'uso del plasma ricco di piastrine per aiutare la guarigione del menisco riparato in artroscopia.","Hanno trovato che quasi tutti questi studi — 15 su 16 — presentano i risultati in modo più favorevole di quanto i dati reali dimostrino.","Non vuol dire che il trattamento sia inutile: vuol dire che, come sempre quando si parla di terapie nuove, conviene affidarsi al giudizio del proprio chirurgo più che a un titolo entusiasta."]},reel:{chir:["16 revisioni sul PRP nella sutura meniscale: quante esagerano i risultati?","15 su 16 (93,8%) contengono almeno una forma di spin bias. AMSTAR 2 criticamente basso nel 68,8%.","[testo a schermo: «94% delle revisioni: risultati esagerati»] Non dice se il PRP funzioni, dice come viene raccontato."],misto:["Le revisioni scientifiche sul PRP nella sutura del menisco esagerano i risultati?","Sì, quasi sempre: 15 su 16 presentano i dati in modo più ottimista del reale.","[testo a schermo: «Leggere con più cautela»] Non vuol dire che il PRP non funzioni."],pazienti:["Anche gli studi scientifici possono raccontare i risultati in modo troppo ottimista.","Su 16 studi sul plasma ricco di piastrine nel menisco, 15 esagerano i risultati.","[testo a schermo: «Meglio affidarsi al chirurgo che al titolo»] Un promemoria di buon senso."]},linkedin:{chir:["Il 94% delle revisioni sul PRP nella sutura meniscale ne esagera i risultati","Revisione sistematica PRISMA (Im, Dajani, Marks, Liu, Hamad, Kremen, Hoefler, Cheung; OJSM, agosto 2026): 16 revisioni sul PRP come augmentazione della sutura meniscale, valutate su 15 categorie predefinite di spin bias e con AMSTAR 2.\n\nAlmeno una forma di spin in 15/16 (93,8%). AMSTAR 2 criticamente basso nel 68,8% delle revisioni.","Livello di evidenza IV, dichiarato dagli stessi autori. Non valuta se il PRP funzioni, valuta come viene comunicato: un promemoria diretto per chi legge solo l'abstract prima di orientare la pratica clinica."],misto:["Le revisioni scientifiche sul PRP nella sutura del menisco tendono a esagerare i risultati","Un'analisi di 16 revisioni pubblicate sul plasma ricco di piastrine come aiuto alla sutura meniscale trova che quasi tutte (15 su 16) presentano i risultati in modo più ottimista di quanto i dati permettano, spesso con una qualità metodologica bassa.\n\nNon significa che il PRP non funzioni.","Significa che il modo in cui la ricerca su questo tema viene raccontata va letto con più cautela del solito, senza fermarsi al solo abstract."],pazienti:["Anche gli studi scientifici possono raccontare i risultati in modo troppo ottimista","Un'analisi ha esaminato 16 revisioni scientifiche sull'uso del plasma ricco di piastrine per aiutare la guarigione del menisco riparato, trovando che quasi tutte presentano i risultati in modo più favorevole di quanto i dati reali dimostrino.","Non vuol dire che il trattamento sia inutile: vuol dire che conviene affidarsi al giudizio del proprio chirurgo più che al titolo di uno studio."]},instagram:{chir:["📊 PRP e sutura meniscale: il 94% delle revisioni esagera i risultati\n\n16 revisioni sistematiche analizzate.","Spin bias in 15/16. AMSTAR 2 criticamente basso nel 68,8%.\n\nNon dice se il PRP funzioni: dice come viene raccontato.","📎 Link in bio · OJSM, agosto 2026"],misto:["📊 Le revisioni sul PRP nel menisco esagerano quasi sempre i risultati\n\n16 revisioni scientifiche esaminate.","15 su 16 presentano i dati in modo più ottimista del reale, spesso con qualità metodologica bassa.","📎 Link in bio"],pazienti:["📊 Anche la scienza può raccontare i risultati in modo troppo ottimista\n\n16 studi sul plasma ricco di piastrine nel menisco.","15 su 16 esagerano i risultati. Meglio affidarsi al chirurgo che al titolo di uno studio.","📎 Il link nella descrizione del profilo"]}},"5":{video:{chir:["Una revisione retrospettiva turca segue 76 pazienti operati fra il 2005 e il 2006 di resezione artroscopica della plica mediopatellare sintomatica, con degenerazione cartilaginea associata: 42 di loro, età media 51 anni, sono stati rivalutati a un follow-up medio di 14 anni con il punteggio WOMAC.","Il miglioramento di dolore e funzione è significativo già a 6 mesi e resta stabile al follow-up finale: il 97,6% valuta il risultato buono o eccellente a 6 mesi, il 92,9% mantiene questa valutazione a 14 anni. Nessun paziente riporta un peggioramento dei sintomi nel tempo, nonostante la degenerazione cartilaginea presente in tutti i casi.","Manca però un gruppo di controllo: lo studio non dimostra che il merito sia della chirurgia piuttosto che della storia naturale della plica sintomatica. Resta comunque un follow-up insolitamente lungo su un gesto — la resezione di plica — che rientra nella tua pratica."],misto:["Uno studio a lungo termine ha seguito pazienti operati per rimuovere in artroscopia una piega di membrana articolare del ginocchio, chiamata plica, che dava fastidio e si accompagnava a segni iniziali di usura della cartilagine.","A distanza di 14 anni in media, la grande maggioranza — quasi il 93% — mantiene un risultato buono o eccellente sui punteggi di dolore e funzione, e nessuno riporta un peggioramento nel tempo.","Manca però un confronto con pazienti non operati: non si può escludere che parte del miglioramento sarebbe arrivato comunque, semplicemente col tempo. Resta comunque un dato raro, su un follow-up così lungo."],pazienti:["Uno studio ha seguito per oltre 13 anni pazienti operati per rimuovere, con un piccolo intervento in artroscopia, una piega di membrana nel ginocchio che causava dolore.","Il risultato è rassicurante: la grande maggioranza dei pazienti ha mantenuto un buon risultato per tutto questo tempo, senza peggioramenti.","Lo studio non ha però confrontato questi pazienti con altri non operati, quindi non si può dire con certezza quanto del merito sia della chirurgia e quanto del tempo che passa."]},reel:{chir:["76 pazienti, resezione di plica mediopatellare, follow-up medio 14 anni.","92,9% mantiene un risultato buono o eccellente al WOMAC. Nessun peggioramento riportato.","[testo a schermo: «14 anni dopo, il risultato tiene»] Nessun gruppo di controllo: non isola il merito della chirurgia."],misto:["Rimuovere una plica fastidiosa nel ginocchio: il beneficio dura?","A 14 anni, quasi il 93% dei pazienti mantiene un buon risultato.","[testo a schermo: «Un beneficio che dura nel tempo»] Manca però un gruppo di confronto."],pazienti:["Un piccolo intervento per una piega fastidiosa nel ginocchio: che risultato dà nel tempo?","A distanza di 14 anni, la maggior parte dei pazienti sta ancora bene.","[testo a schermo: «Un beneficio che dura»] Un dato rassicurante sulla durata."]},linkedin:{chir:["La resezione della plica mediopatellare tiene bene a 13 anni di distanza","Serie retrospettiva turca (Çakar, Güney, Uzun, Gündoğdu, Bilal; J Clin Pract Res, luglio 2026): 42 pazienti su 76 operati di resezione artroscopica della plica mediopatellare con degenerazione cartilaginea, rivalutati a un follow-up medio di 14 anni.\n\nWOMAC buono/eccellente nel 97,6% a 6 mesi, nel 92,9% al follow-up finale. Nessun peggioramento riportato.","Limite centrale: nessun gruppo di controllo, quindi lo studio non isola il contributo della chirurgia dalla storia naturale della plica sintomatica. Resta un follow-up insolitamente lungo per questo tipo di intervento."],misto:["Rimuovere la plica del ginocchio che dà fastidio: un beneficio che dura, secondo uno studio a lungo termine","Uno studio su 42 pazienti operati per rimuovere una piega di membrana articolare (plica) che causava sintomi, con anche segni di usura della cartilagine, mostra un buon risultato mantenuto per oltre 13 anni nel 93% dei casi circa.","Manca però un gruppo di pazienti non operati con cui confrontarsi: non si può escludere che parte del miglioramento sarebbe arrivato comunque nel tempo."],pazienti:["Un piccolo intervento per una piega fastidiosa nel ginocchio, con un beneficio che dura negli anni","Uno studio ha seguito per oltre 13 anni pazienti operati per rimuovere in artroscopia una piccola piega di membrana nel ginocchio che causava dolore: la maggior parte ha mantenuto un buon risultato per tutto questo tempo.","È un dato rassicurante sulla durata del beneficio, anche se lo studio non confronta questi pazienti con altri non operati."]},instagram:{chir:["🦵 Resezione della plica mediopatellare: risultati stabili a 13 anni\n\n42 pazienti su 76 operati, follow-up medio 14 anni.","WOMAC buono/eccellente nel 92,9% al follow-up finale. Nessun peggioramento riportato.\n\nManca però un gruppo di controllo.","📎 Link in bio · J Clin Pract Res, luglio 2026"],misto:["🦵 Rimuovere la plica fastidiosa del ginocchio: un beneficio che dura\n\nStudio a 14 anni su 42 pazienti operati.","Quasi il 93% mantiene un buon risultato, senza peggioramenti nel tempo.","📎 Link in bio"],pazienti:["🦵 Un piccolo intervento, un beneficio che dura negli anni\n\nStudio a lungo termine su una piega fastidiosa del ginocchio.","La maggior parte dei pazienti sta ancora bene a distanza di 13-14 anni.","📎 Il link nella descrizione del profilo"]}},"6":{video:{chir:["Un gruppo cinese analizza retrospettivamente 59 pazienti operati insieme di ricostruzione del LCA e sutura di una lesione meniscale mediale a manico di secchio, con un second-look artroscopico in occasione della rimozione dell'hardware tibiale.","Il grado di sinovializzazione del neolegamento — quanto tessuto sinoviale lo ricopre, classificato come buono, discreto o scarso — si correla fortemente con la guarigione della sutura meniscale: correlazione di 0,724, altamente significativa. Per grado di sinovializzazione, la guarigione va dal 100% nel gruppo buono al 44,4% nel discreto, fino allo 0% nello scarso.","Il limite: le numerosità esatte dei tre sottogruppi non sono riportate nell'abstract, quindi quel 100% e quello 0% potrebbero venire da pochissimi pazienti ciascuno. Resta comunque un indicatore biologico intraoperatorio interessante per una combinazione — LCA più sutura meniscale — che pratichi spesso."],misto:["Uno studio su 59 pazienti operati insieme al legamento crociato anteriore e a una lesione importante del menisco osserva un secondo controllo artroscopico, fatto in un secondo momento, per capire come procede la guarigione.","Il dato interessante: più il nuovo legamento si ricopre di tessuto sinoviale — una sorta di rivestimento biologico naturale dell'articolazione — meglio guarisce anche il menisco riparato nello stesso intervento. La correlazione è forte e statisticamente solida.","È un'osservazione fatta durante un controllo successivo, non uno studio pensato apposta fin dall'inizio per questa domanda, e non sappiamo quanti pazienti compongono ciascun sottogruppo: un segnale interessante, da confermare con studi dedicati."],pazienti:["Uno studio su pazienti operati insieme al legamento crociato e al menisco ha osservato, con un secondo controllo artroscopico, come procede la guarigione di entrambi.","È emerso che un particolare aspetto della guarigione del legamento è collegato a quanto bene guarisce anche il menisco riparato nello stesso intervento — un segnale che i due processi di guarigione, nello stesso ginocchio, si influenzano a vicenda.","È un'osservazione utile soprattutto per i chirurghi, per capire meglio perché alcune guarigioni vanno meglio di altre, più che un cambiamento immediato per chi si opera."]},reel:{chir:["59 pazienti, LCA + sutura meniscale insieme, second-look artroscopico.","Sinovializzazione del neolegamento correlata alla guarigione meniscale: r=0,724, p<0,001.","[testo a schermo: «Più sinovia, meglio guarisce il menisco»] Sottogruppi piccoli non riportati per numerosità."],misto:["Operare insieme crociato e menisco: che cosa predice la guarigione?","Un dettaglio biologico — la ricopertura del nuovo legamento — è collegato alla guarigione del menisco.","[testo a schermo: «I due processi si influenzano a vicenda»] Osservazione da confermare con studi dedicati."],pazienti:["Operare insieme legamento e menisco: come guariscono insieme?","Un aspetto della guarigione del legamento è collegato a quella del menisco riparato.","[testo a schermo: «Un indizio biologico in più»] Utile soprattutto per i chirurghi."]},linkedin:{chir:["Più il neolegamento è ricoperto di sinovia, meglio guarisce il menisco riparato insieme","Studio retrospettivo cinese (Meng, Zhang, Li, Wang, Ren, Wang, Pang, Yue, Cao; OJSM, agosto 2026): 59 pazienti operati di LCA e sutura di lesione meniscale a manico di secchio, second-look artroscopico alla rimozione dell'hardware tibiale.\n\nCorrelazione fra sinovializzazione dell'innesto di LCA e guarigione meniscale: r=0,724, p<0,001. Guarigione 100%/44,4%/0% per grado di sinovializzazione buono/discreto/scarso.","Numerosità dei tre sottogruppi non riportata singolarmente: da leggere con cautela. Riguarda però esattamente la combinazione LCA più sutura meniscale che pratichi spesso, con un indicatore osservabile ai tuoi stessi second-look."],misto:["Quando si opera insieme il legamento crociato e un menisco lesionato, un dettaglio biologico predice come guarirà il menisco","In 59 pazienti operati insieme al legamento crociato anteriore e a una lesione meniscale importante, i chirurghi hanno osservato che più il nuovo legamento si ricopre di tessuto sinoviale, meglio guarisce anche il menisco riparato nello stesso intervento.","È un'osservazione fatta durante un secondo controllo artroscopico, non uno studio pensato apposta per questa domanda fin dall'inizio: un segnale interessante, da confermare con studi dedicati."],pazienti:["Operare insieme legamento e menisco: un segnale biologico che aiuta a capire come andrà la guarigione","Uno studio su pazienti operati insieme al legamento crociato e al menisco mostra che un particolare aspetto della guarigione del legamento, visibile con un secondo controllo artroscopico, è collegato a quanto bene guarisce anche il menisco riparato.","È un'osservazione utile per i chirurghi più che un cambiamento immediato per il paziente: aiuta a capire meglio perché alcune guarigioni vanno meglio di altre."]},instagram:{chir:["🧬 LCA + sutura meniscale: la sinovializzazione predice la guarigione\n\n59 pazienti, second-look artroscopico.","Correlazione forte (r=0,724, p<0,001) fra ricopertura sinoviale del neolegamento e guarigione meniscale.\n\nSottogruppi piccoli non riportati per numerosità.","📎 Link in bio · OJSM, agosto 2026"],misto:["🧬 Operare insieme crociato e menisco: un dettaglio biologico che conta\n\n59 pazienti, controllo con second-look.","Più il nuovo legamento si ricopre di tessuto sinoviale, meglio guarisce anche il menisco riparato insieme.","📎 Link in bio"],pazienti:["🧬 Legamento e menisco operati insieme: come guariscono?\n\nUno studio con un secondo controllo artroscopico.","Un aspetto della guarigione del legamento è collegato a quella del menisco riparato nello stesso intervento.","📎 Il link nella descrizione del profilo"]}},"7":{video:{chir:["Un registro riabilitativo svedese confronta 1.508 pazienti operati di ricostruzione del LCA: 1.317 primaria, 111 in revisione, 80 controlaterale, seguiti fra 12 e 24 mesi su rientro all'attività fisica preinfortunio, forza isocinetica e punteggi riferiti dal paziente.","A 24 mesi, il rientro all'attività preinfortunio è più frequente dopo la primaria — 43,9% — che dopo revisione, 27,1%, o LCA controlaterale, 25,7%. I punteggi riferiti dal paziente favoriscono sempre la primaria, con differenze più marcate nelle donne su autoefficacia del ginocchio e qualità di vita. Le differenze di forza muscolare misurata restano invece contenute, con dimensioni dell'effetto piccole su quasi tutti i confronti.","È un disegno trasversale, non uno studio prospettico costruito apposta per confrontare i tre gruppi, e gli stessi autori invitano a leggere con cautela la rilevanza clinica delle differenze — piccole anche quando statisticamente significative. Resta però un dato di base utile prima di un secondo intervento sul crociato, in revisione o sull'altro ginocchio."],misto:["Un ampio registro riabilitativo svedese ha confrontato oltre 1.500 pazienti operati al legamento crociato anteriore: chi si opera per la prima volta, chi in revisione dopo un fallimento, e chi al ginocchio opposto dopo un secondo infortunio.","A due anni, chi si opera la prima volta torna allo sport al livello di prima più spesso — quasi il 44% — rispetto a chi si opera in revisione o sul secondo ginocchio, dove la percentuale scende a circa un quarto. Anche i punteggi che il paziente stesso riferisce sul proprio ginocchio sono più favorevoli dopo il primo intervento.","Le differenze nella forza muscolare misurata restano invece piccole: il dato più forte riguarda come il paziente si sente e che cosa riesce a fare, non solo i numeri della forza in laboratorio."],pazienti:["Uno studio su oltre 1.500 pazienti operati al legamento crociato anteriore ha confrontato chi si opera per la prima volta con chi si opera una seconda volta — per una revisione o perché si è rotto anche l'altro ginocchio.","A due anni dall'intervento, chi si è operato per la prima volta torna a fare sport al livello di prima più spesso di chi si è operato una seconda volta.","È un dato utile per parlare con realismo, prima di un secondo intervento, di che cosa aspettarsi — senza che questo significhi che il risultato non possa comunque essere buono."]},reel:{chir:["1.508 pazienti, LCA primaria vs revisione vs controlaterale.","Rientro allo sport a 24 mesi: 43,9% vs 27,1% vs 25,7%.","[testo a schermo: «Primaria batte revisione e controlaterale»] Effetti piccoli, disegno trasversale."],misto:["Operarsi una seconda volta al crociato: che cosa cambia per il rientro allo sport?","Meno frequente rispetto al primo intervento, sia in revisione sia sul ginocchio opposto.","[testo a schermo: «Aspettative da calibrare»] La forza muscolare misurata cambia poco."],pazienti:["Se ci si opera una seconda volta al crociato, che cosa aspettarsi?","Il ritorno allo sport al livello di prima è un po' meno frequente.","[testo a schermo: «Aspettative realistiche, non un verdetto»] Un dato utile per il colloquio prima dell'intervento."]},linkedin:{chir:["Dopo revisione o LCA controlaterale, si torna allo sport meno spesso che dopo il primo intervento","Studio trasversale su registro riabilitativo svedese (Piussi, Hamrin Senorski R, Högberg, Cristiani, Thomeé, Samuelsson, Hamrin Senorski E; OJSM, agosto 2026): 1.508 pazienti — 1.317 primaria, 111 revisione, 80 controlaterale — confrontati fra 12 e 24 mesi.\n\nRientro preinfortunio a 24 mesi: 43,9% (primaria) vs 27,1% (revisione) vs 25,7% (controlaterale).","Dimensioni dell'effetto dichiarate piccole dagli stessi autori nonostante la significatività statistica. Disegno trasversale, registro di un solo paese: un dato di base, non una regola assoluta, per calibrare le aspettative prima di un secondo intervento."],misto:["Operarsi una seconda volta al crociato — in revisione o sull'altro ginocchio — rende il ritorno allo sport meno probabile","Un ampio registro svedese su oltre 1.500 pazienti operati al legamento crociato anteriore mostra che chi si opera una seconda volta, sia per una revisione sia per rompersi il crociato dell'altro ginocchio, torna allo sport al livello di prima meno spesso di chi si opera una volta sola.","Le differenze nella forza muscolare misurata restano invece modeste: il dato più forte riguarda quanto il paziente riferisce di sentirsi e di riuscire a fare, non solo i numeri della forza."],pazienti:["Se ci si opera una seconda volta al legamento crociato, le aspettative vanno calibrate con più cautela","Uno studio su oltre 1.500 pazienti mostra che chi si opera una seconda volta al legamento crociato anteriore — per una revisione o perché si è rotto anche l'altro ginocchio — torna allo sport al livello precedente un po' meno spesso di chi si opera una volta sola.","È un dato utile per parlare con realismo, prima dell'intervento, di che cosa aspettarsi da una seconda operazione, senza che questo significhi che il risultato non possa comunque essere buono."]},instagram:{chir:["🏃 Revisione o LCA controlaterale: rientro allo sport meno frequente\n\nRegistro svedese, 1.508 pazienti.","43,9% (primaria) vs 27,1% (revisione) vs 25,7% (controlaterale) a 24 mesi.\n\nEffetti piccoli, disegno trasversale.","📎 Link in bio · OJSM, agosto 2026"],misto:["🏃 Operarsi una seconda volta al crociato: cambia il ritorno allo sport?\n\nRegistro su oltre 1.500 pazienti.","Sì, sia in revisione sia sull'altro ginocchio: il rientro è meno frequente che dopo il primo intervento.","📎 Link in bio"],pazienti:["🏃 Una seconda operazione al crociato: che cosa aspettarsi?\n\nUno studio su oltre 1.500 pazienti.","Il ritorno allo sport come prima è un po' meno frequente — utile saperlo prima di operarsi.","📎 Il link nella descrizione del profilo"]}}};
var TAGS={"1":{linkedin:"#PRP #Osteoarthritis #ResearchIntegrity",instagram:"#PRP #Artrosi #Ginocchio #IntegritaScientifica #Ortopedia #ChirurgiaOrtopedica #Ricerca #SaluteArticolare #Medicina",kw:"PRP artrosi ginocchio · plasma ricco piastrine studio"},"2":{linkedin:"#MeniscalRoot #KneeSurgery #SportsMedicine",instagram:"#Menisco #RadiceMeniscale #Ginocchio #ChirurgiaOrtopedica #Ortopedia #SportsMedicine #SaluteArticolare #Artroscopia #Medicina",kw:"radice menisco slope tibiale · sutura menisco ginocchio"},"3":{linkedin:"#TKA #RoboticSurgery #MAKO",instagram:"#ProtesiGinocchio #ChirurgiaRobotica #MAKO #TKA #Ortopedia #ChirurgiaOrtopedica #Ginocchio #SaluteArticolare #Medicina",kw:"protesi ginocchio robot MAKO · chirurgia robotica ginocchio"},"4":{linkedin:"#PRP #MeniscalRepair #EvidenceBasedMedicine",instagram:"#PRP #Menisco #Ortopedia #ChirurgiaOrtopedica #EvidenceBasedMedicine #Ricerca #SaluteArticolare #Artroscopia #Medicina",kw:"PRP sutura menisco · plasma piastrine menisco evidenza"},"5":{linkedin:"#Plica #KneeArthroscopy #LongTermOutcomes",instagram:"#Plica #Ginocchio #Artroscopia #ChirurgiaOrtopedica #Ortopedia #SaluteArticolare #DolorGinocchio #Medicina #FollowUp",kw:"plica mediopatellare ginocchio · dolore ginocchio plica"},"6":{linkedin:"#ACL #MeniscalRepair #KneeSurgery",instagram:"#LCA #Menisco #ChirurgiaOrtopedica #Ortopedia #Artroscopia #SaluteArticolare #SportsMedicine #Ginocchio #Medicina",kw:"LCA sutura menisco insieme · guarigione menisco riparato"},"7":{linkedin:"#ACLRevision #ReturnToSport #KneeSurgery",instagram:"#LCA #RevisioneLCA #RitornoAlloSport #ChirurgiaOrtopedica #Ortopedia #SportsMedicine #Ginocchio #SaluteArticolare #Medicina",kw:"revisione LCA sport · crociato controlaterale ritorno"}};
var NLB={"1":{prof:["PRP nell'artrosi: un lavoro cinese sotto Expression of Concern","La rivista Experimental and Therapeutic Medicine ha pubblicato un'Expression of Concern su uno studio cinese sugli effetti del plasma ricco di piastrine nell'artrosi di ginocchio tramite soppressione di fattori infiammatori; non è un lavoro mai citato in queste pagine.","Nessun dettaglio pubblico sul motivo dell'avviso: la rivista non lo spiega insieme alla nota. Un promemoria di cautela sull'integrità della letteratura in quest'area, non un giudizio sul PRP in sé."],mix:["Uno studio cinese sul plasma ricco di piastrine nell'artrosi finisce sotto controllo editoriale","La rivista scientifica che lo aveva pubblicato ha reso pubblica una nota ufficiale di attenzione (Expression of Concern) su uno studio cinese sugli effetti del plasma ricco di piastrine nell'artrosi di ginocchio; è un lavoro diverso da quelli già discussi in queste pagine.","Non si sa ancora perché: la rivista non ha reso pubbliche le ragioni. È comunque un segnale che vale la pena conoscere, per chi si informa su questo trattamento."],paz:["Un lavoro scientifico sul plasma ricco di piastrine nell'artrosi è sotto verifica","Una rivista medica ha segnalato ufficialmente dei dubbi su uno studio cinese riguardante il plasma ricco di piastrine nell'artrosi di ginocchio, un trattamento di cui si sente parlare spesso.","Non è ancora chiaro il motivo esatto, ma è giusto saperlo: anche nella ricerca scientifica capita che un lavoro venga rivisto con più attenzione dopo la pubblicazione."],kw:"PRP artrosi ginocchio · plasma ricco piastrine"},"2":{prof:["Radice meniscale: uno slope tibiale più alto alza il rischio di mancata guarigione","Uno studio caso-controllo su 72 rifissazioni della radice meniscale mediale mostra che uno slope tibiale posteriore più alto si associa in modo indipendente al mancato consolidamento a 6 mesi (OR 1,31 per grado; IC 95% 1,04-1,73; p=0,022), mentre età e BMI non risultano fattori di rischio.","Tecnica di fissazione all-inside con ancora, diversa dalla rifissazione transtibiale pull-out: il principio biomeccanico è verosimilmente lo stesso, il numero esatto non è automaticamente trasferibile a ogni tecnica."],mix:["Nella riparazione del menisco lesionato alla radice, l'inclinazione della tibia influenza la guarigione","Uno studio su 72 pazienti operati per riparare la radice del menisco mediale mostra che chi ha un'inclinazione naturale della tibia più marcata guarisce meno spesso completamente, indipendentemente dall'età o dal peso corporeo.","Lo studio riguarda una tecnica di fissazione diversa da quella più diffusa nel tuo contesto: il principio — più inclinazione, più rischio — è probabilmente valido in generale, ma il numero preciso resta legato a questa tecnica specifica."],paz:["Riparare il menisco lesionato alla radice: un dettaglio anatomico che conta per la guarigione","Uno studio su pazienti operati per riparare una lesione del menisco vicino al suo punto di ancoraggio mostra che chi ha una particolare inclinazione naturale dell'osso della tibia guarisce con più difficoltà.","È un fattore che il chirurgo può valutare prima dell'intervento e discutere nel colloquio: non impedisce l'intervento, ma aiuta a capire le probabilità di successo."],kw:"radice menisco slope tibiale · sutura menisco ginocchio"},"3":{prof:["Protesi robotica MAKO: allineamento più preciso, beneficio funzionale ancora incerto","Una meta-analisi di 9 studi comparativi (937 protesi) mostra che il robot MAKO migliora l'angolo di allineamento (differenza media -0,96°; IC 95% -1,26/-0,65) e i punteggi funzionali (SMD 0,46; IC 95% 0,01-0,91) rispetto alla tecnica convenzionale.","Dolore, range di movimento e Forgotten Joint Score restano statisticamente non significativi, con intervalli che non escludono un vantaggio reale: risultati muti, non negativi. Nessuno studio randomizzato incluso."],mix:["La protesi di ginocchio fatta con il robot MAKO è più precisa, ma non è ancora certo che il paziente lo senta di più","Una sintesi di 9 studi su quasi 940 protesi mostra che l'assistenza robotica MAKO allinea la protesi in modo più accurato e migliora alcuni punteggi funzionali standardizzati rispetto alla tecnica tradizionale.","Su dolore, movimento e sensazione di «ginocchio dimenticato» — ciò che il paziente percepisce di più — i risultati non sono ancora chiari: gli studi disponibili sono tutti osservazionali, nessuno randomizzato."],paz:["Protesi di ginocchio con il robot: più precisione tecnica, risultato percepito ancora da chiarire","Una revisione di più studi mostra che l'assistenza robotica MAKO posiziona la protesi in modo più preciso rispetto alla tecnica classica, con alcuni punteggi funzionali migliori.","Non è ancora dimostrato che questa maggiore precisione si traduca in meno dolore o in un ginocchio che il paziente «dimentica» di avere operato: servono studi di qualità più alta per saperlo con certezza."],kw:"protesi ginocchio robot MAKO · chirurgia robotica ginocchio"},"4":{prof:["PRP nella sutura meniscale: il 94% delle revisioni ne esagera i risultati","Una revisione metodologica di 16 sintesi pubblicate sul PRP come augmentazione della sutura meniscale trova almeno una forma di distorsione a favore del trattamento in 15 su 16 (93,8%), con qualità metodologica AMSTAR 2 criticamente bassa nel 68,8% dei casi.","Non dice se il PRP funzioni o no: dice che la sua efficacia, in questo campione di revisioni, è probabilmente presentata in modo più favorevole di quanto i dati sottostanti giustifichino."],mix:["Le revisioni scientifiche sul plasma ricco di piastrine nella sutura del menisco tendono a esagerare i risultati","Un'analisi di 16 revisioni pubblicate sul plasma ricco di piastrine come aiuto alla guarigione del menisco riparato trova che quasi tutte (15 su 16) presentano i risultati in modo più ottimista di quanto i dati permettano, spesso con una qualità metodologica bassa.","Non significa che il PRP non funzioni: significa che il modo in cui la ricerca su questo tema viene raccontata va letto con più cautela del solito."],paz:["Anche gli studi scientifici possono raccontare i risultati in modo troppo ottimista","Un'analisi ha esaminato 16 revisioni scientifiche sull'uso del plasma ricco di piastrine per aiutare la guarigione del menisco riparato, e ha trovato che quasi tutte presentano i risultati in modo più favorevole di quanto i dati reali dimostrino.","Non vuol dire che il trattamento sia inutile: vuol dire che, come per ogni trattamento, conviene affidarsi al giudizio del proprio chirurgo più che al titolo di uno studio."],kw:"PRP sutura menisco · plasma piastrine menisco"},"5":{prof:["Resezione della plica mediopatellare: risultati stabili a 13 anni","Una serie retrospettiva su 42 pazienti operati di resezione artroscopica della plica mediopatellare con degenerazione cartilaginea mostra un risultato buono o eccellente al WOMAC nel 92,9% dei casi a un follow-up medio di 14 anni.","Nessun gruppo di controllo: lo studio non dimostra la superiorità della chirurgia sul trattamento conservativo o sulla storia naturale, solo che il beneficio osservato dopo l'intervento persiste nel tempo."],mix:["Rimuovere la plica del ginocchio che dà fastidio: un beneficio che dura, secondo uno studio a lungo termine","Uno studio su 42 pazienti operati per rimuovere una piega di membrana articolare (plica) che causava sintomi, con anche segni di usura della cartilagine, mostra un buon risultato mantenuto per oltre 13 anni nel 93% dei casi circa.","Manca però un gruppo di pazienti non operati con cui confrontarsi: non si può escludere che parte del miglioramento sarebbe arrivato comunque nel tempo."],paz:["Un piccolo intervento per una piega fastidiosa nel ginocchio, con un beneficio che dura negli anni","Uno studio ha seguito per oltre 13 anni pazienti operati per rimuovere in artroscopia una piccola piega di membrana nel ginocchio che causava dolore: la maggior parte ha mantenuto un buon risultato per tutto questo tempo.","È un dato rassicurante sulla durata del beneficio, anche se lo studio non confronta questi pazienti con altri non operati."],kw:"plica ginocchio artroscopia · dolore ginocchio plica"},"6":{prof:["LCA e sutura meniscale insieme: la sinovializzazione del neolegamento predice la guarigione","In 59 pazienti operati di LCA e sutura di una lesione meniscale a manico di secchio nello stesso tempo chirurgico, il grado di ricopertura sinoviale del neolegamento al second-look si correla fortemente con la guarigione della sutura meniscale (r=0,724; p<0,001).","Numerosità dei tre sottogruppi di sinovializzazione non riportata singolarmente: le percentuali di guarigione (100%/44,4%/0%) potrebbero nascondere gruppi molto piccoli. Studio trasversale su second-look, monocentrico."],mix:["Quando si opera insieme il legamento crociato e un menisco lesionato, un dettaglio biologico predice come guarirà il menisco","In 59 pazienti operati insieme al legamento crociato anteriore e a una lesione meniscale importante, i chirurghi hanno osservato che più il nuovo legamento si ricopre di tessuto sinoviale (una sorta di rivestimento biologico dell'articolazione), meglio guarisce anche il menisco riparato nello stesso intervento.","È un'osservazione fatta durante un secondo controllo artroscopico, non uno studio pensato apposta per questa domanda fin dall'inizio: un segnale interessante, da confermare con studi dedicati."],paz:["Operare insieme legamento e menisco: un segnale biologico che aiuta a capire come andrà la guarigione","Uno studio su pazienti operati insieme al legamento crociato e al menisco mostra che un particolare aspetto della guarigione del legamento, visibile con un secondo controllo artroscopico, è collegato a quanto bene guarisce anche il menisco riparato.","È un'osservazione utile per i chirurghi più che un cambiamento immediato per il paziente: aiuta a capire meglio perché alcune guarigioni vanno meglio di altre."],kw:"LCA sutura menisco insieme · guarigione menisco riparato"},"7":{prof:["Revisione o LCA controlaterale: rientro allo sport meno frequente che dopo la primaria","Un registro riabilitativo svedese su 1.508 pazienti mostra che, a 24 mesi, il rientro all'attività fisica preinfortunio è più frequente dopo LCA primaria (43,9%) che dopo revisione (27,1%) o controlaterale (25,7%), con punteggi riferiti dal paziente sempre a favore della primaria.","Disegno trasversale, non uno studio prospettico dedicato al confronto; dimensioni dell'effetto dichiarate piccole dagli stessi autori nonostante la significatività statistica su alcuni esiti."],mix:["Operarsi una seconda volta al crociato — in revisione o sull'altro ginocchio — rende il ritorno allo sport meno probabile","Un ampio registro svedese su oltre 1.500 pazienti operati al legamento crociato anteriore mostra che chi si opera una seconda volta, sia per una revisione sia per rompersi il crociato dell'altro ginocchio, torna allo sport al livello di prima meno spesso di chi si opera una volta sola.","Le differenze nella forza muscolare misurata restano invece modeste: il dato più forte riguarda quanto il paziente riferisce di sentirsi e di riuscire a fare, non solo i numeri della forza."],paz:["Se ci si opera una seconda volta al legamento crociato, le aspettative vanno calibrate con più cautela","Uno studio su oltre 1.500 pazienti mostra che chi si opera una seconda volta al legamento crociato anteriore — per una revisione o perché si è rotto anche l'altro ginocchio — torna allo sport al livello precedente un po' meno spesso di chi si opera una volta sola.","È un dato utile per parlare con realismo, prima dell'intervento, di che cosa aspettarsi da una seconda operazione, senza che questo significhi che il risultato non possa comunque essere buono."],kw:"revisione LCA sport · crociato controlaterale"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"red",sec:"res",j:"Experimental and Therapeutic Medicine",h:"Un lavoro cinese sul PRP nell'artrosi finisce sotto sorveglianza editoriale",v:"Experimental and Therapeutic Medicine pubblica un'Expression of Concern su uno studio cinese sul plasma ricco di piastrine nell'artrosi di ginocchio: non è un lavoro mai citato da PULSE, ma un segnale di attenzione sull'integrità della letteratura in un'area che segui.",ax:"Huang … Chen",date:"ago 2026",meta:"nota editoriale (Expression of Concern) · [—]",pmid:'42683135',doi:'10.3892/etm.2026.13269',journal:"Experimental and Therapeutic Medicine",authors:"Huang G, Hua S, Yang T, Ma J, Yu W, Chen X",design:"Nota editoriale della rivista (Expression of Concern), non uno studio con dati propri.",pop:"Non applicabile.",results:"Non riportato nell'abstract — l'avviso non è accompagnato da un abstract pubblico su PubMed; è registrato solo il tipo di pubblicazione «Expression of Concern» sul lavoro originale (Huang, Hua, Yang, Ma, Yu, Chen, Experimental and Therapeutic Medicine 2026;32(4):274), dedicato agli effetti del plasma ricco di piastrine sull'artrosi di ginocchio tramite soppressione di fattori infiammatori.",concl:"Non riportato: la rivista non pubblica online, insieme all'avviso, le ragioni della preoccupazione.",limits:"Nessun dettaglio pubblico sul motivo dell'Expression of Concern · non è uno dei lavori mai citati in PULSE, verificato oggi contro l'intero storico e l'archivio · non è possibile stabilire da qui se riguardi i dati, il metodo o un conflitto d'interesse.",perte:"Non tocca una tua citazione passata — controllato oggi l'intero perimetro storico del progetto (154 PMID), nessuna ritrattazione trovata — ma è un promemoria che la letteratura sul PRP nell'artrosi, un'area che segui, non è esente da problemi di integrità: la stessa cautela che la scheda 4 di oggi documenta sulle revisioni sistematiche del PRP nella sutura meniscale."},{n:2,mono:"m-ojsm",dot:"orange",sec:"res",j:"Orthopaedic Journal of Sports Medicine",h:"Uno slope tibiale più alto alza il rischio che la radice meniscale non guarisca",v:"Uno studio caso-controllo coreano su 72 rifissazioni della radice meniscale mediale mostra che uno slope tibiale posteriore più alto predice, in modo indipendente, il mancato consolidamento a 6 mesi (OR 1,31 per grado) — tecnica di fissazione diversa dalla tua, ma il principio si aggiunge alla tensione sull'estrusione meniscale.",ax:"Choi … Victoroff",date:"ago 2026",meta:"studio caso-controllo, due centri · 72 pz (47/25) · [III]",pmid:'42682852',doi:'10.1177/23259671261477913',journal:"Orthopaedic Journal of Sports Medicine",authors:"Choi NH, Yang BS, Lee DM, Victoroff BN",design:"Studio caso-controllo retrospettivo, due centri coreani (marzo 2008-dicembre 2023): rifissazione all-inside con ancora della radice meniscale posteriore mediale (MMPRT), indicata per condromalacia Outerbridge 1-2, estrusione minima (<3 mm) e asse quasi normale. Guarigione valutata su RM a 6 mesi (assenza di segnale iperintenso a tutto spessore o «ghost sign»); slope tibiale posteriore mediale misurato sulla RM sagittale centrale col metodo di Hudek, affidabilità intra-osservatore verificata.",pop:"72 pazienti su 91 arruolati (19 esclusi per età <30 anni, RM di controllo mancante o lesione legamentosa concomitante): 47 nel gruppo guarito, 25 nel gruppo non guarito.",results:"Slope tibiale posteriore mediale significativamente più alto nel gruppo non guarito (5,9°±2,2° contro 4,4°±2,5°; p=0,017). Alla regressione logistica, lo slope si associa in modo indipendente al mancato consolidamento (OR 1,31 per grado; IC 95% 1,04-1,73; p=0,022); età e BMI non sono associati (OR 0,99, IC 95% 0,93-1,08, p=0,759; OR 0,85, IC 95% 0,70-1,02, p=0,079). Affidabilità intra-osservatore della misura eccellente (ICC 0,89; IC 95% 0,76-0,95).",concl:"Gli autori concludono che uno slope tibiale posteriore mediale aumentato è un fattore di rischio per il mancato consolidamento della radice meniscale mediale dopo rifissazione, da considerare nel colloquio preoperatorio col paziente.",limits:"Tecnica di fissazione all-inside con ancora, non la rifissazione transtibiale pull-out che usi tu · disegno retrospettivo, solo associazione, non causalità · misura affidata a un solo osservatore, riproducibilità fra osservatori non valutata · campione dichiarato adeguatamente potenziato dagli autori (potenza 80%, minimo 24 per gruppo), ma resta un singolo studio.",perte:"Alimenta direttamente la tensione T2b: è la prima volta che lo slope tibiale posteriore, non solo l'estrusione o la condrosi femoro-rotulea, viene legato al mancato consolidamento della radice mediale. La tecnica di fissazione studiata è diversa dalla tua (all-inside con ancora, non transtibiale pull-out): il principio biomeccanico — più forza di taglio anteriore con slope aumentato — è verosimilmente lo stesso, ma il numero esatto (OR 1,31) non è automaticamente trasferibile al tuo costrutto."},{n:3,mono:"m-gray",dot:"orange",sec:"res",j:"Frontiers in Bioengineering and Biotechnology",h:"Il robot MAKO migliora l'allineamento della protesi, non chiaramente la funzione",v:"Una meta-analisi di 9 studi comparativi (937 protesi) sul robot MAKO conferma un allineamento più preciso e punteggi funzionali migliori, ma lascia muti dolore, range di movimento e Forgotten Joint Score — lo stesso schema già visto su RACER-Knee, qui su una piattaforma diversa dalla tua.",ax:"Zhang … Chen",date:"ago 2026",meta:"revisione sistematica e meta-analisi di studi comparativi · 9 studi, 937 pz · [III]",pmid:'42682704',doi:'10.3389/fbioe.2026.1892225',journal:"Frontiers in Bioengineering and Biotechnology",authors:"Zhang T, Lou C, Wu D, Ying J, Chen J",design:"Revisione sistematica e meta-analisi (CNKI, Wanfang, Vip, banca dati biomedica cinese, PubMed, Cochrane, Embase, Web of Science, dall'inizio a luglio 2026) di studi comparativi non randomizzati fra protesi totale di ginocchio robot-assistita con sistema MAKO e tecnica convenzionale.",pop:"9 studi (7 caso-controllo retrospettivi, 2 studi prima-dopo), 937 pazienti.",results:"Angolo anca-ginocchio-caviglia (HKA) più vicino al target col MAKO (differenza media -0,96°; IC 95% -1,26/-0,65; p<0,0001) e punteggi funzionali del ginocchio migliori (SMD 0,46; IC 95% 0,01-0,91; p=0,04). Dolore (SMD -0,74; IC 95% -1,55/0,06; p=0,07), range di movimento (differenza media 0,86°; IC 95% -0,23/1,94; p=0,12) e Forgotten Joint Score (SMD 1,06; IC 95% -0,15/2,27; p=0,09) non raggiungono la significatività, con intervalli che non escludono un beneficio reale del robot su nessuno dei tre.",concl:"Gli autori concludono che il MAKO migliora in modo riproducibile l'accuratezza dell'allineamento e i punteggi funzionali standardizzati, incoraggiandone l'uso prioritario nei casi che richiedono alta precisione (deformità complesse), pur segnalando l'eterogeneità delle misure di esito fra gli studi disponibili.",limits:"Nessuno studio randomizzato incluso, solo comparativi osservazionali · dolore, range di movimento e Forgotten Joint Score non significativi con intervalli ampi: non dimostrano equivalenza, sono muti · piattaforma MAKO, non VELYS.",perte:"Sistema MAKO, non VELYS — ma lo schema è lo stesso già visto su RACER-Knee (21 agosto) e sulla revisione critica del 1° settembre: precisione tecnica dimostrata, beneficio funzionale percepito dal paziente ancora incerto sui tre esiti che contano di più in ambulatorio (dolore, movimento, Forgotten Joint Score)."},{n:4,mono:"m-ojsm",dot:"orange",sec:"res",j:"Orthopaedic Journal of Sports Medicine",h:"Il 94% delle revisioni sul PRP nella sutura meniscale ne esagera i risultati",v:"Una revisione metodologica mostra che 15 delle 16 sintesi pubblicate sul PRP nella sutura meniscale contengono almeno una forma di distorsione a favore del trattamento, spesso insieme a una qualità metodologica criticamente bassa — un invito alla cautela prima di fidarsi dell'abstract.",ax:"Im … Cheung",date:"ago 2026",meta:"revisione sistematica di spin bias, PRISMA · 16 revisioni · [IV, dichiarato dagli autori]",pmid:'42682855',doi:'10.1177/23259671261471384',journal:"Orthopaedic Journal of Sports Medicine",authors:"Im C, Dajani AH, Marks A, Liu T, Hamad C, Kremen TJ, Hoefler AH, Cheung EC",design:"Revisione sistematica secondo PRISMA (screening del 14 luglio 2025) delle revisioni sistematiche e meta-analisi sul PRP come augmentazione della sutura meniscale; ogni abstract valutato su 15 categorie predefinite di «spin» (distorsione nella presentazione dei risultati), qualità metodologica del testo completo con AMSTAR 2.",pop:"16 revisioni sistematiche/meta-analisi, selezionate da 1.047 record iniziali.",results:"Almeno una forma di spin bias presente in 15 revisioni su 16 (93,8%). Distorsioni più frequenti: mancato riporto di un intervallo di confidenza ampio (43,8% delle revisioni), conclusione centrata selettivamente sull'esito favorevole con significatività statistica (43,8%), enfasi selettiva sugli esiti di efficacia a favore del PRP (43,8%). Qualità metodologica AMSTAR 2 «criticamente bassa» nel 68,8% delle revisioni. Nessuna associazione significativa fra caratteristiche dello studio, tipo di spin e punteggio AMSTAR 2 (tutti p>0,05).",concl:"Gli autori concludono che lo spin a livello di abstract è molto diffuso nelle revisioni sul PRP per la sutura meniscale, spesso insieme a una bassa affidabilità metodologica, e invitano a una lettura critica di questi abstract prima di orientare la pratica clinica su di essi.",limits:"Livello di evidenza IV dichiarato dagli stessi autori · valuta la forma della presentazione (spin), non rifà l'analisi dei dati originali · non dice se il PRP funzioni o no, dice solo che la sua efficacia è probabilmente sovrastimata nel modo in cui viene comunicata.",perte:"Un promemoria metodologico diretto se usi o consideri il PRP come augmentazione nelle tue suture meniscali: la sintesi che leggi nell'abstract di una revisione sistematica su questo tema ha, in questo campione, quasi il 94% di probabilità di essere presentata in modo più favorevole di quanto i dati sottostanti giustifichino. Stessa cautela già documentata nel progetto sulle meta-analisi di PRP e cellule staminali nell'artrosi (17 e 23 agosto)."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Clinical Practice and Research",h:"La resezione della plica mediopatellare tiene bene a 13 anni di distanza",v:"Una serie retrospettiva turca segue per 14 anni 42 pazienti operati di resezione della plica mediopatellare con degenerazione cartilaginea: il 92,9% mantiene un risultato buono o eccellente, ma senza un gruppo di confronto che isoli il contributo della chirurgia.",ax:"Çakar … Bilal",date:"lug 2026",meta:"serie retrospettiva senza controllo · 42 pz (di 76 operati) · [IV]",pmid:'42676528',doi:'10.14744/cpr.2026.40961',journal:"Journal of Clinical Practice and Research",authors:"Çakar B, Güney A, Uzun E, Gündoğdu MC, Bilal Ö",design:"Revisione retrospettiva di 76 pazienti sottoposti a resezione artroscopica della plica mediopatellare sintomatica con degenerazione cartilaginea associata (2005-2006); 42 pazienti (età media 51,2±12,1 anni) rivalutati a un follow-up medio di 14,0±0,79 anni con il punteggio WOMAC a baseline, 6 mesi e follow-up finale.",pop:"42 pazienti su 76 operati (esclusioni e persi al follow-up), rivalutati a un follow-up medio di 14 anni.",results:"Miglioramento significativo di dolore e funzione a 6 mesi e al follow-up finale (p<0,05). A 6 mesi il 97,6% dei pazienti valuta il risultato buono o eccellente al WOMAC; il 92,9% mantiene questa valutazione al follow-up finale. Nessun paziente riporta un peggioramento dei sintomi nel tempo. Degenerazione cartilaginea presente in tutti i casi, soprattutto al condilo femorale mediale e al polo mediale della rotula.",concl:"Gli autori concludono che la resezione artroscopica della plica mediopatellare sintomatica con degenerazione cartilaginea offre un beneficio clinico duraturo oltre il decennio, anche in presenza di patologia articolare associata, quando le terapie conservative hanno fallito.",limits:"Nessun gruppo di controllo: lo studio non dimostra la superiorità della resezione rispetto al trattamento conservativo o alla storia naturale, solo che il beneficio osservato dopo l'intervento persiste nel tempo · serie a braccio singolo su un campione ridotto dai 76 iniziali · valutazione affidata a un solo punteggio (WOMAC).",perte:"Un follow-up insolitamente lungo (14 anni) su un gesto che esegui — la resezione di plica — con un risultato che va nella direzione che ti aspetti: beneficio stabile nel tempo anche con degenerazione cartilaginea associata. Manca però il confronto che stabilirebbe se il merito sia della chirurgia o della storia naturale della plica sintomatica."},{n:6,mono:"m-ojsm",dot:"green",sec:"res",j:"Orthopaedic Journal of Sports Medicine",h:"Più il neolegamento è ricoperto di sinovia, meglio guarisce il menisco riparato insieme",v:"In 59 pazienti operati di LCA e sutura meniscale a manico di secchio nello stesso tempo, la sinovializzazione del neolegamento al second-look si correla fortemente con la guarigione della sutura (r=0,724) — un indicatore biologico intraoperatorio per una combinazione che pratichi spesso.",ax:"Meng … Cao",date:"ago 2026",meta:"studio retrospettivo, second-look artroscopico · 59 pz · [III]",pmid:'42682973',doi:'10.1177/23259671261472645',journal:"Orthopaedic Journal of Sports Medicine",authors:"Meng B, Zhang Z, Li W, Wang Q, Ren F, Wang R, Pang H, Yue Z, Cao J",design:"Analisi retrospettiva di pazienti operati fra gennaio 2020 e gennaio 2025 di ricostruzione del LCA combinata a sutura di una lesione meniscale mediale a manico di secchio, con second-look artroscopico in occasione della rimozione dell'hardware tibiale. Sinovializzazione dell'innesto di LCA classificata su video artroscopico come buona (>80%), discreta (50-80%) o scarsa (<50%); guarigione meniscale definita come assenza di ri-rottura o necessità di ulteriore riparazione/meniscectomia.",pop:"59 pazienti sottoposti a ricostruzione del LCA e sutura meniscale combinate, con second-look artroscopico.",results:"Tutti i punteggi funzionali (KOOS, Lysholm, IKDC, Tegner) migliorano significativamente dal preoperatorio (p<0,05). Correlazione positiva significativa fra grado di sinovializzazione del LCA e guarigione meniscale (r=0,724; p<0,001). Guarigione complessiva nel 61% dei pazienti (36/59); per grado di sinovializzazione: 100% nel gruppo buono, 44,4% nel discreto, 0% nello scarso. Una piccola lesione superficiale libera di 1-2 mm, descritta come fessura minore, osservata nel 75% dei pazienti (44/59) senza correlare con il fallimento.",concl:"Gli autori concludono che il grado di sinovializzazione del neolegamento del LCA è un indicatore artroscopico utile del potenziale biologico di guarigione intra-articolare, e può informare la valutazione postoperatoria quando si combina la sutura meniscale con la ricostruzione del LCA.",limits:"Numerosità dei tre sottogruppi di sinovializzazione non riportata singolarmente nell'abstract: le percentuali (100%/44,4%/0%) possono nascondere gruppi molto piccoli · disegno trasversale su second-look, non uno studio prospettico disegnato per questa domanda · monocentrico, popolazione cinese.",perte:"Riguarda esattamente la combinazione che pratichi spesso — LCA più sutura meniscale nello stesso tempo chirurgico — e aggiunge un indicatore biologico intraoperatorio (la sinovializzazione del neolegamento) potenzialmente osservabile nei tuoi stessi second-look, quando li esegui."},{n:7,mono:"m-ojsm",dot:"green",sec:"res",j:"Orthopaedic Journal of Sports Medicine",h:"Dopo revisione o LCA controlaterale, si torna allo sport meno spesso che dopo il primo intervento",v:"Un registro riabilitativo svedese su 1.508 pazienti mostra che, a 24 mesi, il rientro allo sport preinfortunio è meno frequente dopo revisione (27,1%) o LCA controlaterale (25,7%) che dopo la primaria (43,9%) — utile per calibrare le aspettative prima di un secondo intervento.",ax:"Piussi … Hamrin Senorski",date:"ago 2026",meta:"coorte di registro riabilitativo, trasversale · 1.508 pz · [III]",pmid:'42682837',doi:'10.1177/23259671261470914',journal:"Orthopaedic Journal of Sports Medicine",authors:"Piussi R, Hamrin Senorski R, Högberg J, Cristiani R, Thomeé R, Samuelsson K, Hamrin Senorski E",design:"Studio trasversale su un registro riabilitativo svedese: pazienti sottoposti a ricostruzione del LCA primaria, in revisione, o controlaterale, confrontati fra 12 e 24 mesi su rientro all'attività fisica preinfortunio (scala di Tegner), forza muscolare isocinetica e punteggi riferiti dal paziente; sottoanalisi per sesso.",pop:"1.508 pazienti: 1.317 primaria, 111 revisione, 80 controlaterale.",results:"A 24 mesi, rientro all'attività fisica preinfortunio più frequente dopo LCA primaria (43,9%) che dopo revisione (27,1%) o controlaterale (25,7%). I punteggi riferiti dal paziente favoriscono la primaria a ogni controllo. Nelle donne, differenze significative su autoefficacia del ginocchio e qualità di vita a favore della primaria. Differenze di forza muscolare limitate; la maggior parte delle differenze statisticamente significative ha dimensione dell'effetto piccola (η² fra 0,007 e 0,056 per gli esiti continui; ω=0,122 per il rientro allo sport).",concl:"Gli autori concludono che revisione e LCA controlaterale si associano a un rientro allo sport meno frequente e a punteggi riferiti dal paziente meno favorevoli rispetto alla primaria fra 12 e 24 mesi, ma invitano a interpretare con cautela la rilevanza clinica, viste le dimensioni dell'effetto piccole sulla maggior parte dei confronti.",limits:"Disegno trasversale, non uno studio prospettico disegnato per il confronto fra i tre gruppi · dimensioni dell'effetto dichiarate piccole dagli stessi autori nonostante la significatività statistica · registro di un solo paese, riabilitazione strutturata non necessariamente sovrapponibile al tuo contesto.",perte:"Un dato di base utile nel colloquio prima di una revisione o di un secondo LCA controlaterale: le aspettative di rientro allo sport a 1-2 anni vanno calibrate più in basso rispetto al primo intervento, anche se le differenze di forza muscolare misurata restano modeste."}];
var SUGGQ=[{k:"kol",n:"Brian N. Victoroff",w:"Case Western Reserve University, Cleveland (Ohio)",r:"Ultimo autore dello studio caso-controllo di oggi sullo slope tibiale posteriore come fattore di rischio per il mancato consolidamento della radice meniscale mediale (PICK del giorno) — corrispondenza tecnica diretta con la tua tensione aperta T2b su radice ed estrusione meniscale, anche se la sua tecnica di fissazione (all-inside con ancora) è diversa dalla tua transtibiale pull-out."}];
var BRIEF_TEXT="Giovedì 3 settembre. Sette lavori oggi, tre arancioni e un rosso. Il rosso non è un richiamo di dispositivo: è un'Expression of Concern editoriale su uno studio cinese sul PRP nell'artrosi di ginocchio, mai citato in queste pagine — verificato oggi l'intero perimetro storico, 146 citazioni, nessuna ritrattazione. Il pick è uno studio caso-controllo coreano su 72 rifissazioni della radice meniscale mediale: uno slope tibiale posteriore più alto alza in modo indipendente il rischio di mancato consolidamento a 6 mesi, un grado in più di slope vale il 31% di rischio in più. La tecnica di fissazione studiata è però quella all-inside con ancora, diversa dalla transtibiale pull-out: il principio è probabilmente lo stesso, il numero esatto no. Alimenta la tensione T2b sull'estrusione meniscale. Gli altri due arancioni riguardano la qualità dell'evidenza più che una tecnica specifica: una meta-analisi di 9 studi sul robot MAKO conferma un allineamento più preciso ma lascia dolore, movimento e Forgotten Joint Score senza risposta chiara; e una revisione metodologica mostra che il 94% delle sintesi pubblicate sul PRP nella sutura meniscale ne esagera i risultati. Fra i verdi: una serie turca segue per 14 anni pazienti operati di resezione della plica mediopatellare, con un risultato che tiene ma senza gruppo di controllo; uno studio cinese lega la sinovializzazione del neolegamento di LCA alla guarigione di una sutura meniscale eseguita nello stesso intervento; e un registro riabilitativo svedese su 1.508 pazienti mostra che, dopo revisione o LCA controlaterale, si torna allo sport meno spesso che dopo il primo intervento. Il raccoglitore notturno non è passato stanotte: richiami, Swissmedic, congressi, società e destino dei verdetti restano non verificati per oggi, le ritrattazioni sono state comunque ricontrollate a mano su tutto il perimetro storico del progetto.";
var BRIEF_DIALOGO=[{chi:"A",t:"Buongiorno. Sette lavori oggi, tre arancioni e un rosso — ma il rosso non è un richiamo di dispositivo."},{chi:"B",t:"Che cos'è, allora?"},{chi:"A",t:"Una rivista ha pubblicato un'Expression of Concern su uno studio cinese sul PRP nell'artrosi. Non è mai stato citato qui: controllate oggi tutte le 146 citazioni storiche del progetto, nessuna ritrattazione trovata."},{chi:"B",t:"E il lavoro del giorno, qual è?"},{chi:"A",t:"Uno studio caso-controllo coreano su 72 rifissazioni della radice meniscale mediale. Chi ha uno slope tibiale posteriore più alto guarisce meno spesso: un grado in più di slope, il 31% di rischio in più di non consolidare."},{chi:"B",t:"Quindi per la tua tecnica cosa cambia?"},{chi:"A",t:"La fissazione studiata è all-inside con ancora, non la transtibiale pull-out che uso io. Il principio — più inclinazione, più forza di taglio, più rischio — è probabilmente lo stesso, ma il numero preciso resta legato a questa tecnica."},{chi:"B",t:"E gli altri due arancioni?"},{chi:"A",t:"Riguardano più la qualità dell'evidenza che una tecnica in sé. Una meta-analisi sul robot MAKO conferma un allineamento più preciso, ma dolore, movimento e Forgotten Joint Score restano senza risposta chiara."},{chi:"B",t:"E il terzo?"},{chi:"A",t:"Una revisione mostra che quasi il 94% delle sintesi pubblicate sul PRP nella sutura meniscale esagera i risultati rispetto ai dati reali. Vale la stessa cautela per quasi tutto ciò che si legge sul PRP in questi giorni."},{chi:"B",t:"E fra i verdi c'è qualcosa di utile per la pratica quotidiana?"},{chi:"A",t:"Sì: un registro svedese su oltre 1.500 pazienti mostra che, dopo una revisione o un secondo crociato, si torna allo sport meno spesso che dopo il primo intervento — utile per calibrare le aspettative nel colloquio."},{chi:"B",t:"E il raccoglitore notturno di stanotte?"},{chi:"A",t:"Non è passato. Richiami, congressi e destino dei verdetti restano non verificati, ma le ritrattazioni le abbiamo controllate comunque a mano su tutto lo storico."}];
